ht:100%;object-fit:cover}.db-thumb b{position:absolute;right:2px;bottom:2px;padding:2px 4px;border-radius:4px;color:#fff;background:#111827;font-size:.5rem}.db-more{color:#667085;font-size:.65rem;font-weight:850}.db-summary{display:grid;min-width:0;flex:1}.db-summary span,.db-summary em{color:#667085;font-size:.6rem}.db-summary strong{margin:3px 0;color:#101828;font-size:.86rem}.db-summary em{font-style:normal;color:#98a2b3}.db-card>footer{border-top:1px solid #f0f2f5}.db-card>footer>span{color:#667085;font-size:.63rem}.db-card>footer>span i{color:#2563eb;margin-right:5px}.db-card>footer>div{display:flex;gap:6px}.db-card button,.db-modal footer button,.db-modal footer a{display:inline-flex;align-items:center;gap:5px;padding:7px 9px;border:1px solid #dfe3e8;border-radius:8px;color:#475467;background:#fff;font-size:.6rem;font-weight:800;text-decoration:none;cursor:pointer}.db-card button:hover{border-color:#d0d5dd;background:#f8fafc}.db-card button.danger,.db-modal footer button.cancel{color:#b42318}.db-empty{text-align:center;padding:52px 20px}.db-empty>div{display:grid;width:54px;height:54px;margin:0 auto 12px;place-items:center;border-radius:15px;color:#2563eb;background:#eff6ff;font-size:1.1rem}.db-empty h3{margin:0;font-size:.9rem}.db-empty p{margin:5px 0;color:#667085;font-size:.65rem}.db-overlay{position:fixed;inset:0;z-index:3000;display:flex;justify-content:flex-end;background:rgba(15,23,42,.5);backdrop-filter:blur(3px)}.db-modal{width:min(720px,100%);height:100%;display:flex;flex-direction:column;overflow:hidden;background:#f8fafc;box-shadow:-20px 0 60px rgba(15,23,42,.2)}.db-modal>header{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:20px;border-bottom:1px solid #e4e7ec;background:#fff}.db-modal header small{display:block;color:#2563eb;font-size:.56rem;font-weight:950;letter-spacing:.14em}.db-modal header h2{margin:3px 0 2px;font-size:1.15rem}.db-modal header span{color:#98a2b3;font-size:.6rem}.db-modal header button{display: